import{dynasties}from"../data.js";export function DynastyCard({dynastyId:n,onExpand:a}){const s=dynasties.find(a=>a.id===n);if(!s)return document.createElement("div");const e=document.createElement("div");e.className="dynasty-card",e.style.setProperty("--dynasty-color",s.color),e.innerHTML=`\n    <div class="dynasty-card-header">\n      <div class="dynasty-card-title-row">\n        <h3 class="dynasty-card-name">${s.name}</h3>\n        <button class="expand-btn" aria-label="Expand details for ${s.name}">+</button>\n      </div>\n      <span class="dynasty-card-period">${s.period}</span>\n<span class="dynasty-card-capital">Capital: ${s.capital}</span>\n      ${s.link?`<a class="dynasty-card-link" href="${s.link}">View Full Explorer →</a>`:""}      ${s.link?`<a class="dynasty-card-link" href="${s.link}">View Full Explorer →</a>`:""}      ${s.link?`<a class="dynasty-card-link" href="${s.link}">View Full Explorer →</a>`:""}\n      ${s.link?`<a class="dynasty-card-link" href="${s.link}">View Full Explorer →</a>`:""}      ${s.link?`<a class="dynasty-card-link" href="${s.link}">View Full Explorer →</a>`:""}\n    </div>    <div class="dynasty-card-body">\n      <div class="dynasty-card-stats">\n        <div class="stat">\n          <span class="stat-label">Founder</span>\n          <span class="stat-value">${s.founders}</span>\n        </div>\n        <div class="stat">\n          <span class="stat-label">Peak Extent</span>\n          <span class="stat-value">${s.peakExtent}</span>\n        </div>\n        <div class="stat">\n          <span class="stat-label">Governance</span>\n          <span class="stat-value">${s.governance}</span>\n        </div>\n      </div>\n      <div class="dynasty-card-rulers">\n        <h4>Notable Rulers</h4>\n        <ul>\n          ${s.notableRulers.map(n=>`\n            <li>\n              <strong>${n.name}</strong> <span class="ruler-reign">${n.reign}</span>\n              <p class="ruler-achievement">${n.achievement}</p>\n            </li>\n          `).join("")}\n        </ul>\n      </div>\n      ${s.explorerPath?`\n        <div class="dynasty-card-action">\n          <a class="dynasty-explorer-link" href="${s.explorerPath}">${s.explorerLabel||"Open Explorer"}</a>\n        </div>\n      `:""}\n      <div class="dynasty-card-detail" style="display:none">\n        <div class="detail-section">\n          <h4>Contributions</h4>\n          <ul class="contributions-list">\n            ${s.contributions.map(n=>`<li>${n}</li>`).join("")}\n          </ul>\n        </div>\n        <div class="detail-section">\n          <h4>Art & Architecture</h4>\n          <p>${s.art}</p>\n        </div>\n        <div class="detail-section">\n          <h4>Decline</h4>\n          <p>${s.decline}</p>\n        </div>\n      </div>\n    </div>\n  `;const t=e.querySelector(".expand-btn"),l=e.querySelector(".dynasty-card-detail");return t.addEventListener("click",()=>{const n="none"===l.style.display;l.style.display=n?"block":"none",t.textContent=n?"−":"+",t.setAttribute("aria-expanded",n?"true":"false")}),e}export function DynastyCardsList({era:n}){const a=document.createElement("div");a.className="dynasty-cards-grid";return("all"===n?dynasties:dynasties.filter(a=>a.era===n)).forEach(n=>{a.appendChild(DynastyCard({dynastyId:n.id}))}),a}